// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.benchmark;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator.Theme;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.RepositoryException;
import org.eclipse.rdf4j.repository.manager.RemoteRepositoryManager;
import org.eclipse.rdf4j.repository.manager.RepositoryInfo;
import org.eclipse.rdf4j.repository.util.RDFInserter;

/** Uploads the generated physical theme datasets to a selected local RDF4J Server repository. */
public final class UploadThemeDataToRdf4jServer {

	private static final String SERVER_URL = "http://localhost:8080/rdf4j-server";

	private UploadThemeDataToRdf4jServer() {
	}

	public static void main(String[] args) {
		RemoteRepositoryManager manager = RemoteRepositoryManager.getInstance(SERVER_URL);
		try {
			List<RepositoryInfo> repositories = new ArrayList<>(manager.getAllRepositoryInfos());
			repositories.sort(Comparator.comparing(RepositoryInfo::getId));
			if (repositories.isEmpty()) {
				System.out.println("No repositories are available on " + SERVER_URL);
				return;
			}
			RepositoryInfo selected;
			try (Scanner input = new Scanner(System.in)) {
				selected = selectRepository(repositories, input);
			}
			if (selected == null) {
				return;
			}

			Repository repository = manager.getRepository(selected.getId());
			if (repository == null || !repository.isWritable()) {
				throw new RepositoryException("Repository is unavailable or read-only: " + selected.getId());
			}

			System.out.println("Uploading generated theme data to repository '" + selected.getId() + "'.");
			System.out.println("Existing repository data will be preserved.");
			try (RepositoryConnection connection = repository.getConnection()) {
				uploadPhysicalThemes(connection);
			}
			System.out.println("All theme data was committed to repository '" + selected.getId() + "'.");
		} finally {
			manager.shutDown();
		}
	}

	private static RepositoryInfo selectRepository(List<RepositoryInfo> repositories, Scanner input) {
		System.out.println("Repositories on " + SERVER_URL + ":");
		for (int i = 0; i < repositories.size(); i++) {
			RepositoryInfo repository = repositories.get(i);
			System.out.printf("%d. %s%s%n", i + 1, repository.getId(),
					repository.isWritable() ? "" : " (read-only)");
		}
		if (repositories.stream().noneMatch(RepositoryInfo::isWritable)) {
			System.out.println("No writable repositories are available on " + SERVER_URL);
			return null;
		}

		while (true) {
			System.out.print("Select a writable repository by number: ");
			if (!input.hasNextLine()) {
				System.out.println("No repository selected.");
				return null;
			}

			String selection = input.nextLine().strip();
			try {
				int index = Integer.parseInt(selection) - 1;
				if (index < 0 || index >= repositories.size()) {
					System.out.println("Enter a number from the listed range.");
					continue;
				}

				RepositoryInfo repository = repositories.get(index);
				if (!repository.isWritable()) {
					System.out.println("That repository is read-only; choose a writable repository.");
					continue;
				}
				return repository;
			} catch (NumberFormatException e) {
				System.out.println("Enter the number of the repository to use.");
			}
		}
	}

	private static void uploadPhysicalThemes(RepositoryConnection connection) {
		boolean previousThemeCommitted = false;
		for (Theme theme : Theme.values()) {
			if (theme == Theme.ANALYTICS || theme == Theme.EXPLORATION) {
				continue;
			}
			System.out.println("Generating and uploading " + theme + "...");
			boolean transactionNeedsRollback = true;
			try {
				connection.begin(IsolationLevels.READ_COMMITTED);
				ThemeDataSetGenerator.generate(theme, new RDFInserter(connection));
				System.out.println("Finished uploading " + theme + " theme data; committing transaction...");
				connection.commit();
				transactionNeedsRollback = false;
			} catch (RuntimeException | Error uploadFailure) {
				boolean rollbackSucceeded = false;
				if (transactionNeedsRollback) {
					try {
						connection.rollback();
						rollbackSucceeded = true;
					} catch (RepositoryException rollbackFailure) {
						uploadFailure.addSuppressed(rollbackFailure);
					}
				}
				System.err.println("Failed to upload theme " + theme + ". "
						+ (rollbackSucceeded ? "Its transaction was rolled back."
								: "Rollback of its transaction could not be confirmed."));
				if (previousThemeCommitted) {
					System.err.println("Earlier theme commits remain in the repository; rerunning this uploader is safe.");
				}
				throw uploadFailure;
			}
			previousThemeCommitted = true;
			System.out.println("Committed " + theme + " theme data.");
		}
	}
}
